// skill-pack-router (opencode plugin) -- generated by the skill pack installer, do not edit here.
// Adds a short synthetic note to each user message naming the pack skills that fit it,
// using the same router as the Claude Code / Codex / Antigravity hooks. Never throws.
// Disable: SKILL_ROUTER_DISABLE=1 opencode
// file:// URL of the router, so the import also works on Windows paths
const ROUTER_URL = "__SKILL_PACK_ROUTER_URL__"

export const SkillPackRouter = async ({ directory } = {}) => {
  let router = null
  try {
    router = await import(ROUTER_URL)
  } catch {
    return {}
  }
  return {
    "chat.message": async (input, output) => {
      try {
        if (process.env.SKILL_ROUTER_DISABLE === "1" || !output || !Array.isArray(output.parts)) return
        const text = output.parts
          .filter((p) => p && p.type === "text" && !p.synthetic && typeof p.text === "string")
          .map((p) => p.text)
          .join("\n")
        if (!text.trim()) return
        const r = router.route(text, directory || process.cwd())
        if (!r.picked.length) return
        const first = output.parts.find((p) => p && p.type === "text") || {}
        output.parts.push({
          id: "prt_" + Date.now().toString(16) + Math.random().toString(36).slice(2, 12),
          sessionID: first.sessionID || input.sessionID,
          messageID: first.messageID || input.messageID || (output.message && output.message.id),
          type: "text",
          text: router.renderContext(r.picked),
          synthetic: true,
        })
      } catch {
        /* never break a prompt */
      }
    },
  }
}
